const filas = $input.all().map(i => i.json);

// Normalizar textos (sin tildes, sin espacios, minúsculas)
function normalizarTexto(valor) {
  if (valor === null || valor === undefined) return '';
  return String(valor)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')   // quitar tildes
    .replace(/[^\w\s]/g, ' ')          // quitar signos
    .replace(/\s+/g, '')               // quitar TODOS los espacios
    .trim()
    .toLowerCase();
}

function sinDatos(valor) {
  if (valor === null || valor === undefined || String(valor).trim() === '') {
    return 'Sin datos';
  }
  return String(valor).trim();
}

function determinarArea(maquina) {
  const m = normalizarTexto(maquina);
  if (m.includes('selladora') || m.includes('sellado')) return 'selladoras';
  if (m.includes('extrusora')) return 'extrusoras';
  if (m.includes('impresora')) return 'impresoras';
  return 'otras';
}

const resultado = {
  resumen_general: {
    total_novedades: 0,
    total_maquinas_unicas: 0,
    total_responsables_unicos: 0
  },
  responsables: {
    total: 0,
    detalle: []
  },
  areas: {
    selladoras: { total_novedades: 0, total_maquinas: 0, maquinas: [] },
    extrusoras:  { total_novedades: 0, total_maquinas: 0, maquinas: [] },
    impresoras:  { total_novedades: 0, total_maquinas: 0, maquinas: [] },
    otras:       { total_novedades: 0, total_maquinas: 0, maquinas: [] }
  }
};

const responsablesMap = {};
const maquinasGlobal = new Set();
const areasTemp = {
  selladoras: {},
  extrusoras: {},
  impresoras: {},
  otras: {}
};

for (const fila of filas) {
  const maquinaOriginal = sinDatos(fila['PENDIENTE DE LA SEMANA   24  ( 8 -13 JUNIO)']);
  if (normalizarTexto(maquinaOriginal) === 'maquina') continue;

  const observacion = sinDatos(fila.col_3);
  const diagnostico = sinDatos(fila.col_5);
  const responsableOriginal = sinDatos(fila.col_6);

  resultado.resumen_general.total_novedades++;
  maquinasGlobal.add(normalizarTexto(maquinaOriginal));

  // Responsables
  if (responsableOriginal !== 'Sin datos') {
    const keyResp = normalizarTexto(responsableOriginal);
    if (!responsablesMap[keyResp]) {
      responsablesMap[keyResp] = { nombre: responsableOriginal, total_novedades: 0 };
    }
    responsablesMap[keyResp].total_novedades++;
  }

  const area = determinarArea(maquinaOriginal);
  resultado.areas[area].total_novedades++;

  const maquinaKey = normalizarTexto(maquinaOriginal);
  if (!areasTemp[area][maquinaKey]) {
    areasTemp[area][maquinaKey] = {
      maquina: maquinaOriginal,
      total_novedades: 0,
      responsables: {},
      pendientes: []
    };
  }

  const maquina = areasTemp[area][maquinaKey];
  maquina.total_novedades++;
  maquina.pendientes.push({
    observacion,
    diagnostico_solucion: diagnostico,
    responsable: responsableOriginal
  });

  if (responsableOriginal !== 'Sin datos') {
    const r = normalizarTexto(responsableOriginal);
    if (!maquina.responsables[r]) {
      maquina.responsables[r] = { nombre: responsableOriginal, cantidad: 0 };
    }
    maquina.responsables[r].cantidad++;
  }
}

// Convertir áreas temporales a arrays
for (const area of Object.keys(areasTemp)) {
  const maquinas = Object.values(areasTemp[area]);
  resultado.areas[area].total_maquinas = maquinas.length;
  resultado.areas[area].maquinas = maquinas.map(m => ({
    maquina: m.maquina,
    total_novedades: m.total_novedades,
    responsables: Object.values(m.responsables).sort((a, b) => b.cantidad - a.cantidad),
    pendientes: m.pendientes
  }));
}

// Responsables globales
resultado.responsables.detalle = Object.values(responsablesMap)
  .sort((a, b) => b.total_novedades - a.total_novedades);
resultado.responsables.total = resultado.responsables.detalle.length;

resultado.resumen_general.total_maquinas_unicas = maquinasGlobal.size;
resultado.resumen_general.total_responsables_unicos = resultado.responsables.total;
resultado.resumen_general.responsables_mas_mencionados = resultado.responsables.detalle.slice(0, 5);

// Eliminar la sección "otras" si no tiene máquinas
if (resultado.areas.otras.total_maquinas === 0) {
  delete resultado.areas.otras;
}

return [{ json: resultado }];

const raw = $input.first().json.output || $input.first().json.text || '';
const maxTelegram = 4096;

// Asegurar saltos de línea claros y quitar Markdown residual
const limpio = raw
  .replace(/\*/g, '-')          // cambiar asteriscos por guiones
  .replace(/\n{3,}/g, '\n\n')   // normalizar saltos múltiples
  .replace(/^\s*[-•]\s/gm, '- ') // unificar viñetas
  .trim();

// Si excede el límite, truncar con puntos suspensivos
const final = limpio.length > maxTelegram
  ? limpio.substring(0, maxTelegram - 3) + '...'
  : limpio;

return [{ json: { mensaje: final } }];
